//! Board resource bundles for the RP2350B pin map.
//!
//! Each struct groups the pins, peripheral instances, PWM slices and DMA
//! channels one subsystem needs. The structs and the `split_resources!` helper
//! are generated by the [`assign_resources`] crate, so `main` can move the
//! fields out of the embassy `Peripherals` struct in one call.
//!
//! Pin grouping (ADR-0022): motor/encoders 4–12, RGB 13–15, I2C0 16–17,
//! IMU 18–22, camera power/UART 23–25, I2C1 26–27, `LiDAR` 28–30,
//! expansion 32–37, touch 38–39, battery ADC 40, display 41–47, panel power 0,
//! rangefinder control 1–3 and 31. No GPIOs are spare.

#![allow(clippy::missing_docs_in_private_items)]

use assign_resources::assign_resources;
use embassy_rp::{Peri, peripherals};

assign_resources! {
    /// Pins and slices used by the TB6612FNG motor driver and motor encoders.
    ///
    /// Two-track configuration on one contiguous GPIO block: left PWM on GPIO 4
    /// (slice 2, channel A), right PWM on GPIO 7 (slice 3, channel B). Direction
    /// pins are direct-GPIO outputs (IN1/IN2 per channel), and the encoders use
    /// PWM input mode on slices 4 and 5. Keeping the whole harness on GPIO 4–12
    /// lets it escape the package as a single bundle instead of weaving between
    /// the UART, LED and IMU groups.
    motor: MotorDriverResources {
        /// Left motor PWM slice (slice 2).
        left_pwm_slice: PWM_SLICE2,
        /// Left motor PWM pin (GPIO 4).
        left_pwm_pin: PIN_4,
        /// Left motor forward direction pin (GPIO 5).
        left_fwd: PIN_5,
        /// Left motor backward direction pin (GPIO 6).
        left_bwd: PIN_6,
        /// Right motor PWM slice (slice 3).
        right_pwm_slice: PWM_SLICE3,
        /// Right motor PWM pin (GPIO 7).
        right_pwm_pin: PIN_7,
        /// Right motor forward direction pin (GPIO 8).
        right_fwd: PIN_8,
        /// Right motor backward direction pin (GPIO 10).
        right_bwd: PIN_10,
        /// TB6612FNG standby pin (active high, GPIO 12).
        standby: PIN_12,
        /// Left encoder PWM slice (slice 4).
        enc_left_slice: PWM_SLICE4,
        /// Left encoder input pin (GPIO 9).
        enc_left_pin: PIN_9,
        /// Right encoder PWM slice (slice 5).
        enc_right_slice: PWM_SLICE5,
        /// Right encoder input pin (GPIO 11).
        enc_right_pin: PIN_11,
    }

    /// Pins and PIO block for the common-cathode RGB status LED.
    rgb: RgbLedResources {
        /// PIO block used for the three PWM state machines.
        pio: PIO1,
        /// Red channel (GPIO 13).
        red: PIN_13,
        /// Green channel (GPIO 14).
        green: PIN_14,
        /// Blue channel (GPIO 15).
        blue: PIN_15,
    }

    /// Resources for the COIN-D6 360° spinning dTOF `LiDAR`.
    ///
    /// Runs on **core1** over a dedicated UART0 peripheral on GPIO 28 (TX) and
    /// GPIO 29 (RX), with a TPS22917 high-side load-switch enable on GPIO 30.
    /// The three pins are adjacent, so the `LiDAR` harness leaves the MCU as one
    /// bundle. The sensor is off at boot; the driver task powers its 5 V branch
    /// on demand and streams scan data at 10 Hz (~230 400 baud). The UART is
    /// quiesced and its TX pin tri-stated before the branch is powered down
    /// (ADR-0023).
    lidar: D6LidarResources {
        /// UART0 TX — connect to `LiDAR` RX (GPIO 28).
        uart_tx: PIN_28,
        /// UART0 RX — connect to `LiDAR` TX (GPIO 29).
        uart_rx: PIN_29,
        /// TPS22917 high-side load-switch enable (active-high, GPIO 30).
        power_enable: PIN_30,
        /// UART0 peripheral instance.
        uart: UART0,
    }

    /// Resources for the Grove Vision AI V2 camera module.
    ///
    /// The camera runs on a **PIO0 UART**: GPIO 24 is MCU TX, GPIO 25 is MCU RX,
    /// and a TPS22917 high-side load-switch enable is on GPIO 23. The module's
    /// Grove input is 5 V (`GROVE_5V_IN`) and its UART is 3.3 V. Using PIO for
    /// the camera leaves UART1 free for the buffered expansion link on GPIO
    /// 36/37 (ADR-0021). The UART is quiesced and its pins tri-stated before the
    /// branch is powered down (ADR-0023).
    ///
    /// The module runs on-device ML inference and reports
    /// results over serial. Full duplex (unlike the D6), since the module expects
    /// host commands and returns results over the same UART.
    ai_cam: AiCamResources {
        /// PIO UART TX — connect to AI cam RX (GPIO 24).
        uart_tx: PIN_24,
        /// PIO UART RX — connect to AI cam TX (GPIO 25).
        uart_rx: PIN_25,
        /// TPS22917 high-side load-switch enable (active-high, GPIO 23).
        power_enable: PIN_23,
        /// PIO block used for the camera UART.
        pio: PIO0,
    }

    /// Pin and DMA resources for the shared `SPI1` panel bus (ADR-0008).
    ///
    /// The panel occupies the contiguous high GPIO block 41–47, with the touch
    /// controller on 38/39 and the battery ADC keeping GPIO 40. `DMA_CH6`
    /// carries the bus's transmit direction and `DMA_CH7` its receive direction,
    /// because the bus is full duplex. The panel's 5 V branch is switched by a
    /// TPS22917 high-side load switch enabled by GPIO 0, which is physically
    /// adjacent to GPIO 47 at the QFN ring's wrap point (ADR-0024).
    panel: PanelResources {
        /// `SPI1` peripheral instance.
        spi: SPI1,
        /// SPI clock (GPIO 42).
        sck: PIN_42,
        /// SPI data out / MOSI (GPIO 43).
        mosi: PIN_43,
        /// SPI data in / MISO (GPIO 44).
        miso: PIN_44,
        /// DMA channel for the bus's transmit direction.
        tx_dma: DMA_CH6,
        /// DMA channel for the bus's receive direction.
        rx_dma: DMA_CH7,
        /// Display chip select (GPIO 41).
        display_cs: PIN_41,
        /// Display data/command (GPIO 45).
        dc: PIN_45,
        /// Display reset (GPIO 46).
        rst: PIN_46,
        /// Display backlight (GPIO 47).
        blk: PIN_47,
        /// Touch chip select (GPIO 38).
        touch_cs: PIN_38,
        /// Touch pen-down interrupt (GPIO 39, active-low with a pull-up).
        penirq: PIN_39,
        /// TPS22917 high-side load-switch enable (`PANEL_PWR`, active-high, GPIO 0).
        power_enable: PIN_0,
    }

    /// SPI0 and control lines for the ICM-20948 IMU.
    imu: ImuResources {
        /// SPI0 peripheral instance.
        spi: SPI0,
        /// SPI clock (GPIO 18).
        sck: PIN_18,
        /// SPI data out / MOSI (GPIO 19).
        mosi: PIN_19,
        /// SPI data in / MISO (GPIO 20).
        miso: PIN_20,
        /// IMU chip select (GPIO 21).
        cs: PIN_21,
        /// DMA channel for SPI0 TX.
        tx_dma: DMA_CH1,
        /// DMA channel for SPI0 RX.
        rx_dma: DMA_CH2,
    }

    /// I2C0 bus for the front-down VL53L0X rangefinder.
    rangefinder0: Rangefinder0Resources {
        /// I2C0 peripheral instance.
        i2c: I2C0,
        /// I2C0 data line (GPIO 16).
        sda: PIN_16,
        /// I2C0 clock line (GPIO 17).
        scl: PIN_17,
        /// Active-low shutdown, driven open-drain (GPIO 1).
        xshut: PIN_1,
        /// Interrupt input (GPIO 2).
        interrupt: PIN_2,
    }

    /// I2C1 bus for the rear-down VL53L0X rangefinder.
    rangefinder1: Rangefinder1Resources {
        /// I2C1 peripheral instance.
        i2c: I2C1,
        /// I2C1 data line (GPIO 26).
        sda: PIN_26,
        /// I2C1 clock line (GPIO 27).
        scl: PIN_27,
        /// Active-low shutdown, driven open-drain (GPIO 3).
        xshut: PIN_3,
        /// Interrupt input (GPIO 31).
        interrupt: PIN_31,
    }

    /// Battery-voltage ADC input.
    battery: BatteryResources {
        /// ADC peripheral instance.
        adc: ADC,
        /// Battery-sense ADC pin (GPIO 40 / ADC0).
        pin: PIN_40,
    }

    /// Flash storage for calibration persistence.
    storage: StorageResources {
        /// Internal flash peripheral.
        flash: FLASH,
        /// DMA channel used by the flash driver.
        dma: DMA_CH0,
    }

    /// Resources for the 7-pin expansion connector (not yet implemented).
    ///
    /// The 5 V branch is switched by a TPS22917 high-side load switch enabled by
    /// `EXP_PWR` on GPIO 32. The connector uses UART1 on GPIO 36/37, with reset/
    /// enable on GPIO 34, boot-mode on GPIO 35, and interrupt/status on GPIO 33.
    /// Its logic is 3.3 V; the 5 V pin is power, not a logic reference. Quiesce
    /// UART1 and hold `en`/`boot` low before switching the branch off (ADR-0023).
    expansion: ExpansionResources {
        /// UART1 peripheral instance.
        uart: UART1,
        /// UART1 TX DMA channel.
        tx_dma: DMA_CH4,
        /// UART1 RX DMA channel.
        rx_dma: DMA_CH5,
        /// TPS22917 high-side load-switch enable (`EXP_PWR`, active-high, GPIO 32).
        power_enable: PIN_32,
        /// Expansion interrupt/status line (GPIO 33).
        irq: PIN_33,
        /// Expansion enable line (GPIO 34).
        en: PIN_34,
        /// Expansion boot-mode line (GPIO 35).
        boot: PIN_35,
        /// UART1 TX to the expansion board (GPIO 36).
        tx: PIN_36,
        /// UART1 RX from the expansion board (GPIO 37).
        rx: PIN_37,
    }

    /// The second CPU core, which runs the LiDAR driver.
    core: CoreResources {
        /// Core1 peripheral instance.
        core1: CORE1,
    }
}
